import unittest
from program import run

class T(unittest.TestCase):
    def test_case_00(self):
        self.assertEqual(run(['3', '1', '2']), {'n': 3, 'mean': 4.333333333333333, 'max': 6, 'grade': 'low'})
    def test_case_01(self):
        self.assertEqual(run(['10', '0', '7', 'x']), {'n': 2, 'mean': 13.5, 'max': 17, 'grade': 'low'})
    def test_case_02(self):
        self.assertEqual(run([' 5 ', '-2', '8']), {'n': 2, 'mean': 9.0, 'max': 13, 'grade': 'low'})
    def test_case_03(self):
        self.assertEqual(run(['4:2', '9:1', 'bad']), {'n': 0, 'mean': 0.0, 'max': 0, 'grade': 'low'})
    def test_case_04(self):
        self.assertEqual(run(['12', '12', '1']), {'n': 3, 'mean': 20.333333333333332, 'max': 25, 'grade': 'low'})
    def test_case_05(self):
        self.assertEqual(run(['0']), {'n': 0, 'mean': 0.0, 'max': 0, 'grade': 'low'})
    def test_case_06(self):
        self.assertEqual(run(['6', '6', '6', '6']), {'n': 4, 'mean': 15.0, 'max': 24, 'grade': 'high'})
    def test_case_07(self):
        self.assertEqual(run(['2', 'hello', '40']), {'n': 2, 'mean': 22.0, 'max': 42, 'grade': 'low'})

if __name__ == '__main__':
    unittest.main()
